@startuml
class Library {
}
class User {
  +securityDeposit : double
  +phone : string
  +email : string
  +mail : string
}
class BorrowableItem {
  +libraryCode : string
  +location : string
}
class Book extends BorrowableItem {
  +publisher : string
}
class MagazineIssue extends BorrowableItem {
  +publicationDate : date
  +publisher : string
}
class MusicCD extends BorrowableItem {
  +publisher : string
  +artist : string
}
class VHSFilm extends BorrowableItem {
  +duration : int
  +publisher : string
}
class DVDFilm extends BorrowableItem {
  +duration : int
  +publisher : string
}
class Author {
}
class Actor {
}
class Request {
}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
User "0..1" -- "*" BorrowableItem : borrows
Book "1..*" -- "1..*" Author : written by
VHSFilm "1..*" -- "1..*" Actor : features
Library "0..*" -- "0..*" Library : sends request to
Request "0..*" -- "1" User : made by
Request "0..*" -- "1" BorrowableItem : for
@enduml

